def rotations(cells):
    result=set()
    cur=cells
    for _ in range(4):
        minr=min(r for r,c in cur);minc=min(c for r,c in cur)
        norm=tuple(sorted((r-minr,c-minc) for r,c in cur));result.add(norm)
        cur={(c,-r) for r,c in cur}
    return result

def tile_search(cells, definitions, node_limit=1000000):
    global nodes,memo,sol,plac_by_cell,areas,ptypes
    counts={typ:n for typ,sh,n in definitions}; areas={typ:len(sh) for typ,sh,n in definitions};ptypes=list(counts)
    plac_by_cell=defaultdict(list); placements=[]
    for typ,shape,n in definitions:
        for orient in rotations(shape):
            hh=max(r for r,c in orient)+1;ww=max(c for r,c in orient)+1
            for ar in range(25-hh+1):
              for ac in range(10-ww+1):
                loc={(ar+r,ac+c) for r,c in orient}
                if loc<=cells:
                    mask=sum(1<<(r*10+c) for r,c in loc)
                    p=(typ,ar,ac,orient,mask)
                    placements.append(p)
                    for cell in loc:plac_by_cell[cell].append(p)
    for cell in plac_by_cell:
        plac_by_cell[cell]=list({(p[0],p[4]):p for p in plac_by_cell[cell]}.values())
        plac_by_cell[cell].sort(key=lambda p:areas[p[0]],reverse=True)
    full=sum(1<<(r*10+c) for r,c in cells)
    nodes=0;memo=set();sol=None;start=time.time()
    def rec(rem,cnt,path):
      global nodes,sol
      nodes+=1
      if nodes>node_limit:return False
      if not rem:
        if not any(cnt.values()):sol=path.copy();return True
        return False
      key=(rem,tuple(cnt[t] for t in ptypes))
      if key in memo:return False
      bestopts=None;temp=rem
      while temp:
        bit=temp&-temp;idx=bit.bit_length()-1;cell=(idx//10,idx%10);temp-=bit
        opts=[p for p in plac_by_cell[cell] if cnt[p[0]] and (p[4]&rem)==p[4]]
        if not opts:
          memo.add(key);return False
        if bestopts is None or len(opts)<len(bestopts):
          bestopts=opts
          if len(opts)==1:break
      for p in bestopts:
        typ=p[0];cnt[typ]-=1
        if rec(rem^p[4],cnt,path+[p]):return True
        cnt[typ]+=1
      memo.add(key);return False
    ok=rec(full,counts.copy(),[])
    return ok,nodes,len(memo),time.time()-start,sol,placements
